package study

import (
	"bufio"
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"time"
)

const (
	RunHistorySchemaVersion = 1
	RunHistoryDirName       = "runs"
	RunHistoryFileName      = "tasks.jsonl"
	RunHistorySummaryName   = "summary.md"
)

type RunHistoryRecord struct {
	SchemaVersion int        `json:"schema_version"`
	Key           string     `json:"key"`
	Study         string     `json:"study"`
	RunID         string     `json:"run_id"`
	TaskID        string     `json:"task_id"`
	Kind          TaskKind   `json:"kind"`
	Status        TaskStatus `json:"status"`

	DimensionRef string     `json:"dimension_ref,omitempty"`
	Dimension    string     `json:"dimension,omitempty"`
	Source       string     `json:"source,omitempty"`
	SourceKind   SourceKind `json:"source_kind,omitempty"`
	OutputPath   string     `json:"output_path,omitempty"`

	StartedAt   *time.Time `json:"started_at,omitempty"`
	CompletedAt *time.Time `json:"completed_at,omitempty"`
	DurationMS  int64      `json:"duration_ms,omitempty"`
	Attempts    int        `json:"attempts,omitempty"`

	Runtime    string `json:"runtime,omitempty"`
	Provider   string `json:"provider,omitempty"`
	Model      string `json:"model,omitempty"`
	AgentRunID string `json:"agent_run_id,omitempty"`

	InputTokensKnown  bool  `json:"input_tokens_known"`
	InputTokens       int64 `json:"input_tokens,omitempty"`
	OutputTokensKnown bool  `json:"output_tokens_known"`
	OutputTokens      int64 `json:"output_tokens,omitempty"`
	TotalTokensKnown  bool  `json:"total_tokens_known"`
	TotalTokens       int64 `json:"total_tokens,omitempty"`

	CostKnown    bool    `json:"cost_known"`
	CostAmount   float64 `json:"cost_amount,omitempty"`
	CostCurrency string  `json:"cost_currency,omitempty"`
	CostEstimate bool    `json:"cost_estimate,omitempty"`
	CostSource   string  `json:"cost_source,omitempty"`

	ValidationStatus       ValidationStatus `json:"validation_status,omitempty"`
	ValidationPassedChecks int              `json:"validation_passed_checks,omitempty"`
	ValidationFailedChecks int              `json:"validation_failed_checks,omitempty"`
	ErrorCode              string           `json:"error_code,omitempty"`
	ErrorMessage           string           `json:"error_message,omitempty"`
	RecordedAt             time.Time        `json:"recorded_at"`
}

func RunHistoryPath(study Study) string {
	return filepath.Join(study.Path, RunStateDirName, RunHistoryDirName, RunHistoryFileName)
}

func RunHistorySummaryPath(study Study) string {
	return filepath.Join(study.Path, RunStateDirName, RunHistoryDirName, RunHistorySummaryName)
}

func AppendRunHistory(study Study, state RunState, task TaskState) error {
	existing, err := readRunHistoryKeys(RunHistoryPath(study))
	if err != nil {
		return err
	}
	return appendRunHistoryWithKeys(study, state, task, existing)
}

func appendRunHistoryWithKeys(study Study, state RunState, task TaskState, existing map[string]bool) error {
	if !terminalTaskStatus(task.Status) || task.CompletedAt == nil {
		return nil
	}
	record := NewRunHistoryRecord(study, state, task, time.Now().UTC())
	if existing[record.Key] {
		return nil
	}
	path := RunHistoryPath(study)
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	data, err := json.Marshal(record)
	if err != nil {
		return err
	}
	previous, err := os.ReadFile(path)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	previous = trimInvalidTrailingRunHistory(previous)
	if len(previous) > 0 && previous[len(previous)-1] != '\n' {
		previous = append(previous, '\n')
	}
	contents := append(previous, append(data, '\n')...)
	if err := atomicWriteRunHistory(path, contents); err != nil {
		return err
	}
	existing[record.Key] = true
	return nil
}

func trimInvalidTrailingRunHistory(data []byte) []byte {
	trimmed := bytes.TrimRight(data, "\r\n")
	if len(trimmed) == 0 {
		return nil
	}
	lineStart := bytes.LastIndexByte(trimmed, '\n') + 1
	if json.Valid(bytes.TrimSpace(trimmed[lineStart:])) {
		return data
	}
	return append([]byte(nil), trimmed[:lineStart]...)
}

func atomicWriteRunHistory(path string, data []byte) error {
	tmp, err := os.CreateTemp(filepath.Dir(path), ".tasks.*.jsonl.tmp")
	if err != nil {
		return err
	}
	tmpPath := tmp.Name()
	defer os.Remove(tmpPath)
	if _, err = tmp.Write(data); err == nil {
		err = tmp.Sync()
	}
	if closeErr := tmp.Close(); err == nil {
		err = closeErr
	}
	if err != nil {
		return err
	}
	if err := os.Chmod(tmpPath, 0o644); err != nil {
		return err
	}
	return os.Rename(tmpPath, path)
}

func SyncRunHistory(study Study, state RunState) error {
	existing, err := readRunHistoryKeys(RunHistoryPath(study))
	if err != nil {
		return err
	}
	for _, task := range state.Tasks {
		if err := appendRunHistoryWithKeys(study, state, task, existing); err != nil {
			return err
		}
	}
	return WriteRunHistorySummary(study, state)
}

func NewRunHistoryRecord(study Study, state RunState, task TaskState, recordedAt time.Time) RunHistoryRecord {
	if recordedAt.IsZero() {
		recordedAt = time.Now().UTC()
	}
	record := RunHistoryRecord{
		SchemaVersion: RunHistorySchemaVersion,
		Study:         study.Name,
		RunID:         state.RunID,
		TaskID:        task.ID,
		Kind:          task.Kind,
		Status:        task.Status,
		DimensionRef:  task.DimensionRef,
		Dimension:     task.Dimension,
		Source:        task.Source,
		SourceKind:    task.SourceKind,
		OutputPath:    task.OutputPath,
		StartedAt:     cloneTimePtr(task.StartedAt),
		CompletedAt:   cloneTimePtr(task.CompletedAt),
		Attempts:      task.Attempts,
		Runtime:       task.Agent.Runtime,
		Provider:      task.Agent.Provider,
		Model:         task.Agent.Model,
		AgentRunID:    task.Agent.RunID,
		RecordedAt:    recordedAt,
	}
	if record.Runtime == "" {
		record.Runtime = state.Config.Runtime
	}
	if record.Model == "" {
		record.Model = state.Config.Model
	}
	record.InputTokensKnown = task.Agent.Usage.InputTokensKnown
	record.InputTokens = task.Agent.Usage.InputTokens
	record.OutputTokensKnown = task.Agent.Usage.OutputTokensKnown
	record.OutputTokens = task.Agent.Usage.OutputTokens
	record.TotalTokensKnown = task.Agent.Usage.TotalTokensKnown
	record.TotalTokens = task.Agent.Usage.TotalTokens
	if task.Agent.Cost != nil {
		record.CostKnown = true
		record.CostAmount = task.Agent.Cost.Amount
		record.CostCurrency = task.Agent.Cost.Currency
		record.CostEstimate = task.Agent.Cost.Estimate
		record.CostSource = task.Agent.Cost.Source
	}
	if task.Validation != nil {
		record.ValidationStatus = task.Validation.Status
		record.ValidationPassedChecks = task.Validation.PassedChecks
		record.ValidationFailedChecks = task.Validation.FailedChecks
	}
	if task.LastError != nil {
		record.ErrorCode = task.LastError.Code
		record.ErrorMessage = task.LastError.Message
	}
	if task.StartedAt != nil && task.CompletedAt != nil {
		record.DurationMS = task.CompletedAt.Sub(*task.StartedAt).Milliseconds()
		if record.DurationMS < 0 {
			record.DurationMS = 0
		}
	}
	record.Key = runHistoryKey(record)
	return record
}

func LoadRunHistory(study Study) ([]RunHistoryRecord, error) {
	path := RunHistoryPath(study)
	file, err := os.Open(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, err
	}
	defer file.Close()
	return readRunHistory(file)
}

func readRunHistory(r io.Reader) ([]RunHistoryRecord, error) {
	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 0, 64*1024), 4*1024*1024)
	var records []RunHistoryRecord
	var pending []byte
	for scanner.Scan() {
		line := append([]byte(nil), scanner.Bytes()...)
		if len(pending) > 0 {
			record, err := decodeRunHistoryRecord(pending)
			if err != nil {
				return nil, err
			}
			records = append(records, record)
		}
		if len(line) == 0 {
			pending = nil
			continue
		}
		pending = line
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	if len(pending) > 0 {
		record, err := decodeRunHistoryRecord(pending)
		if err == nil {
			records = append(records, record)
		}
		// A crash or full disk can leave only the final JSONL record partial.
		// Earlier malformed records still fail above because ignoring them would
		// hide ledger corruption rather than recover an interrupted append.
	}
	return records, nil
}

func decodeRunHistoryRecord(line []byte) (RunHistoryRecord, error) {
	var record RunHistoryRecord
	if err := json.Unmarshal(line, &record); err != nil {
		return RunHistoryRecord{}, err
	}
	return record, nil
}

func readRunHistoryKeys(path string) (map[string]bool, error) {
	file, err := os.Open(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return map[string]bool{}, nil
		}
		return nil, err
	}
	defer file.Close()
	records, err := readRunHistory(file)
	if err != nil {
		return nil, err
	}
	keys := make(map[string]bool, len(records))
	for _, record := range records {
		keys[record.Key] = true
	}
	return keys, nil
}

func terminalTaskStatus(status TaskStatus) bool {
	return status == TaskStatusCompleted || status == TaskStatusFailed || status == TaskStatusCancelled || status == TaskStatusSkipped
}

func runHistoryKey(record RunHistoryRecord) string {
	completed := ""
	if record.CompletedAt != nil {
		completed = record.CompletedAt.UTC().Format(time.RFC3339Nano)
	}
	return fmt.Sprintf("%s|%s|%d|%s", record.RunID, record.TaskID, record.Attempts, completed)
}

func cloneTimePtr(t *time.Time) *time.Time {
	if t == nil {
		return nil
	}
	out := *t
	return &out
}

package study

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

func WriteRunHistorySummary(study Study, state RunState) error {
	records, err := LoadRunHistory(study)
	if err != nil {
		return err
	}
	content := RenderRunHistorySummary(study, state, records, time.Now().UTC())
	path := RunHistorySummaryPath(study)
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	return os.WriteFile(path, []byte(content), 0o644)
}

func RenderRunHistorySummary(study Study, state RunState, records []RunHistoryRecord, now time.Time) string {
	if now.IsZero() {
		now = time.Now().UTC()
	}
	var b strings.Builder
	fmt.Fprintf(&b, "# Study Run Summary\n\n")
	fmt.Fprintf(&b, "- Study: `%s`\n", study.Name)
	fmt.Fprintf(&b, "- Updated: `%s`\n", now.UTC().Format(time.RFC3339))
	fmt.Fprintf(&b, "- Study progress state: `%s`\n", filepath.Join(RunStateDirName, RunStateFileName))
	fmt.Fprintf(&b, "- Ledger: `%s`\n\n", filepath.Join(RunStateDirName, RunHistoryDirName, RunHistoryFileName))

	counts := historyCounts(records)
	pending := remainingTasks(state)
	fmt.Fprintf(&b, "## Status\n\n")
	fmt.Fprintf(&b, "| Metric | Value |\n| --- | ---: |\n")
	fmt.Fprintf(&b, "| Runs recorded | %d |\n", len(records))
	fmt.Fprintf(&b, "| Completed | %d |\n", counts.completed)
	fmt.Fprintf(&b, "| Failed | %d |\n", counts.failed)
	fmt.Fprintf(&b, "| Cancelled | %d |\n", counts.cancelled)
	fmt.Fprintf(&b, "| Skipped | %d |\n", counts.skipped)
	fmt.Fprintf(&b, "| Remaining tasks | %d |\n", len(pending))
	fmt.Fprintf(&b, "| Dimensions seen | %d |\n", len(counts.dimensions))
	fmt.Fprintf(&b, "| Sources seen | %d |\n\n", len(counts.sources))

	writeRemaining(&b, pending)
	writeDimensionSummary(&b, records)
	writeSourceSummary(&b, records)
	writeRuntimeSummary(&b, records)
	writeRecentRuns(&b, records)
	writeSlowestRuns(&b, records)
	writeFailedRuns(&b, records)
	return b.String()
}

type historyCounter struct {
	completed  int
	failed     int
	cancelled  int
	skipped    int
	dimensions map[string]bool
	sources    map[string]bool
}

func historyCounts(records []RunHistoryRecord) historyCounter {
	out := historyCounter{dimensions: map[string]bool{}, sources: map[string]bool{}}
	for _, record := range records {
		switch record.Status {
		case TaskStatusCompleted:
			out.completed++
		case TaskStatusFailed:
			out.failed++
		case TaskStatusCancelled:
			out.cancelled++
		case TaskStatusSkipped:
			out.skipped++
		}
		if record.DimensionRef != "" {
			out.dimensions[record.DimensionRef] = true
		}
		if record.Source != "" {
			out.sources[record.Source] = true
		}
	}
	return out
}

func remainingTasks(state RunState) []TaskState {
	var out []TaskState
	for _, task := range state.Tasks {
		if !terminalTaskStatus(task.Status) {
			out = append(out, task)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

func writeRemaining(b *strings.Builder, tasks []TaskState) {
	fmt.Fprintf(b, "## Remaining Work\n\n")
	if len(tasks) == 0 {
		fmt.Fprintf(b, "No remaining tasks in the current run state.\n\n")
		return
	}
	fmt.Fprintf(b, "| Dimension | Source | Kind | Status |\n| --- | --- | --- | --- |\n")
	for _, task := range tasks {
		fmt.Fprintf(b, "| %s | %s | %s | %s |\n", md(task.DimensionRef), md(displaySource(task)), task.Kind, task.Status)
	}
	fmt.Fprintf(b, "\n")
}

func writeDimensionSummary(b *strings.Builder, records []RunHistoryRecord) {
	type agg struct {
		rows []RunHistoryRecord
	}
	items := map[string]*agg{}
	for _, record := range records {
		key := record.DimensionRef
		if key == "" {
			key = "(none)"
		}
		if items[key] == nil {
			items[key] = &agg{}
		}
		items[key].rows = append(items[key].rows, record)
	}
	keys := sortedKeys(items)
	fmt.Fprintf(b, "## Dimensions\n\n")
	if len(keys) == 0 {
		fmt.Fprintf(b, "No runs recorded yet.\n\n")
		return
	}
	fmt.Fprintf(b, "| Dimension | Runs | Completed | Failed | Avg Duration | Tokens | Cost |\n| --- | ---: | ---: | ---: | ---: | ---: | ---: |\n")
	for _, key := range keys {
		a := summarizeRecords(items[key].rows)
		fmt.Fprintf(b, "| %s | %d | %d | %d | %s | %s | %s |\n", md(key), a.runs, a.completed, a.failed, formatDuration(a.avgDuration), formatIntKnown(a.totalTokens, a.totalTokensKnown), formatCost(a.costAmount, a.costCurrency, a.costKnown))
	}
	fmt.Fprintf(b, "\n")
}

func writeSourceSummary(b *strings.Builder, records []RunHistoryRecord) {
	items := map[string][]RunHistoryRecord{}
	for _, record := range records {
		if record.Kind != TaskKindAnalysis {
			continue
		}
		items[record.Source] = append(items[record.Source], record)
	}
	keys := sortedRecordKeys(items)
	fmt.Fprintf(b, "## Sources\n\n")
	if len(keys) == 0 {
		fmt.Fprintf(b, "No source runs recorded yet.\n\n")
		return
	}
	fmt.Fprintf(b, "| Source | Runs | Completed | Failed | Avg Duration | Tokens | Cost |\n| --- | ---: | ---: | ---: | ---: | ---: | ---: |\n")
	for _, key := range keys {
		a := summarizeRecords(items[key])
		fmt.Fprintf(b, "| %s | %d | %d | %d | %s | %s | %s |\n", md(key), a.runs, a.completed, a.failed, formatDuration(a.avgDuration), formatIntKnown(a.totalTokens, a.totalTokensKnown), formatCost(a.costAmount, a.costCurrency, a.costKnown))
	}
	fmt.Fprintf(b, "\n")
}

func writeRuntimeSummary(b *strings.Builder, records []RunHistoryRecord) {
	items := map[string][]RunHistoryRecord{}
	for _, record := range records {
		key := strings.Join([]string{emptyDash(record.Runtime), emptyDash(record.Provider), emptyDash(record.Model)}, " / ")
		items[key] = append(items[key], record)
	}
	keys := sortedRecordKeys(items)
	fmt.Fprintf(b, "## Runtime And Model\n\n")
	if len(keys) == 0 {
		fmt.Fprintf(b, "No runtime metadata recorded yet.\n\n")
		return
	}
	fmt.Fprintf(b, "| Runtime / Provider / Model | Runs | Completed | Failed | Avg Duration | Tokens | Cost |\n| --- | ---: | ---: | ---: | ---: | ---: | ---: |\n")
	for _, key := range keys {
		a := summarizeRecords(items[key])
		fmt.Fprintf(b, "| %s | %d | %d | %d | %s | %s | %s |\n", md(key), a.runs, a.completed, a.failed, formatDuration(a.avgDuration), formatIntKnown(a.totalTokens, a.totalTokensKnown), formatCost(a.costAmount, a.costCurrency, a.costKnown))
	}
	fmt.Fprintf(b, "\n")
}

func writeRecentRuns(b *strings.Builder, records []RunHistoryRecord) {
	rows := append([]RunHistoryRecord(nil), records...)
	sort.Slice(rows, func(i, j int) bool { return timeAfter(rows[i].CompletedAt, rows[j].CompletedAt) })
	if len(rows) > 20 {
		rows = rows[:20]
	}
	fmt.Fprintf(b, "## Recent Runs\n\n")
	writeRunTable(b, rows, "No recent runs recorded yet.")
}

func writeSlowestRuns(b *strings.Builder, records []RunHistoryRecord) {
	rows := append([]RunHistoryRecord(nil), records...)
	sort.Slice(rows, func(i, j int) bool { return rows[i].DurationMS > rows[j].DurationMS })
	if len(rows) > 10 {
		rows = rows[:10]
	}
	fmt.Fprintf(b, "## Slowest Runs\n\n")
	writeRunTable(b, rows, "No duration data recorded yet.")
}

func writeFailedRuns(b *strings.Builder, records []RunHistoryRecord) {
	var rows []RunHistoryRecord
	for _, record := range records {
		if record.Status == TaskStatusFailed || record.Status == TaskStatusCancelled {
			rows = append(rows, record)
		}
	}
	sort.Slice(rows, func(i, j int) bool { return timeAfter(rows[i].CompletedAt, rows[j].CompletedAt) })
	fmt.Fprintf(b, "## Failed Or Cancelled Runs\n\n")
	if len(rows) == 0 {
		fmt.Fprintf(b, "No failed or cancelled runs recorded.\n\n")
		return
	}
	fmt.Fprintf(b, "| Completed | Dimension | Source | Status | Error |\n| --- | --- | --- | --- | --- |\n")
	for _, row := range rows {
		fmt.Fprintf(b, "| %s | %s | %s | %s | %s |\n", formatTime(row.CompletedAt), md(row.DimensionRef), md(displayRecordSource(row)), row.Status, md(firstNonEmpty(row.ErrorMessage, row.ErrorCode, "-")))
	}
	fmt.Fprintf(b, "\n")
}

func writeRunTable(b *strings.Builder, rows []RunHistoryRecord, empty string) {
	if len(rows) == 0 {
		fmt.Fprintf(b, "%s\n\n", empty)
		return
	}
	fmt.Fprintf(b, "| Completed | Dimension | Source | Kind | Status | Duration | Model | Tokens | Cost |\n| --- | --- | --- | --- | --- | ---: | --- | ---: | ---: |\n")
	for _, row := range rows {
		fmt.Fprintf(b, "| %s | %s | %s | %s | %s | %s | %s | %s | %s |\n", formatTime(row.CompletedAt), md(row.DimensionRef), md(displayRecordSource(row)), row.Kind, row.Status, formatDuration(time.Duration(row.DurationMS)*time.Millisecond), md(emptyDash(row.Model)), formatIntKnown(row.TotalTokens, row.TotalTokensKnown), formatCost(row.CostAmount, row.CostCurrency, row.CostKnown))
	}
	fmt.Fprintf(b, "\n")
}

type recordSummary struct {
	runs             int
	completed        int
	failed           int
	totalDuration    time.Duration
	avgDuration      time.Duration
	totalTokens      int64
	totalTokensKnown bool
	costAmount       float64
	costCurrency     string
	costKnown        bool
}

func summarizeRecords(records []RunHistoryRecord) recordSummary {
	var out recordSummary
	for _, record := range records {
		out.runs++
		if record.Status == TaskStatusCompleted {
			out.completed++
		}
		if record.Status == TaskStatusFailed {
			out.failed++
		}
		out.totalDuration += time.Duration(record.DurationMS) * time.Millisecond
		if record.TotalTokensKnown {
			out.totalTokensKnown = true
			out.totalTokens += record.TotalTokens
		}
		if record.CostKnown {
			out.costKnown = true
			out.costAmount += record.CostAmount
			if out.costCurrency == "" {
				out.costCurrency = record.CostCurrency
			}
			if out.costCurrency != record.CostCurrency {
				out.costCurrency = "mixed"
			}
		}
	}
	if out.runs > 0 {
		out.avgDuration = out.totalDuration / time.Duration(out.runs)
	}
	return out
}

func sortedKeys[T any](m map[string]T) []string {
	keys := make([]string, 0, len(m))
	for key := range m {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	return keys
}

func sortedRecordKeys(m map[string][]RunHistoryRecord) []string {
	return sortedKeys(m)
}

func displaySource(task TaskState) string {
	if task.Source == "" {
		return "(synthesis)"
	}
	return task.Source
}

func displayRecordSource(record RunHistoryRecord) string {
	if record.Source == "" {
		return "(synthesis)"
	}
	return record.Source
}

func formatDuration(d time.Duration) string {
	if d <= 0 {
		return "-"
	}
	d = d.Round(time.Second)
	if d < time.Minute {
		return d.String()
	}
	return fmt.Sprintf("%dm%02ds", int(d.Minutes()), int(d.Seconds())%60)
}

func formatIntKnown(v int64, known bool) string {
	if !known {
		return "-"
	}
	return fmt.Sprintf("%d", v)
}

func formatCost(amount float64, currency string, known bool) string {
	if !known {
		return "-"
	}
	if currency == "" {
		currency = "cost"
	}
	return fmt.Sprintf("%.4f %s", amount, currency)
}

func formatTime(t *time.Time) string {
	if t == nil {
		return "-"
	}
	return t.UTC().Format(time.RFC3339)
}

func timeAfter(a, b *time.Time) bool {
	if a == nil {
		return false
	}
	if b == nil {
		return true
	}
	return a.After(*b)
}

func md(s string) string {
	if s == "" {
		return "-"
	}
	s = strings.ReplaceAll(s, "|", "\\|")
	s = strings.ReplaceAll(s, "\n", " ")
	return s
}

func emptyDash(s string) string {
	if s == "" {
		return "-"
	}
	return s
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if value != "" {
			return value
		}
	}
	return ""
}

