)

func git(dir string, args ...string) string {
	cmd := exec.Command("git", append([]string{"-C", dir}, args...)...)
	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0", "LC_ALL=C")
	out, err := cmd.CombinedOutput()
	if err != nil {
		panic(fmt.Sprintf("git %v: %s: %v", args, out, err))
	}
	return string(out)
}

func write(path, content string) {
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		panic(err)
	}
}

func main() {
	repo := filepath.Join(os.TempDir(), "pubprobe-repo")
	os.RemoveAll(repo)
	os.MkdirAll(repo, 0o755)
	git(repo, "init", "-q", "-b", "main")
	git(repo, "config", "user.name", "t")
	git(repo, "config", "user.email", "t@t")
	write(repo+"/owned.txt", "before\n")
	write(repo+"/staged.txt", "before\n")
	git(repo, "add", ".")
	git(repo, "commit", "-qm", "initial")

	write(repo+"/owned.txt", "after\n")
	write(repo+"/staged.txt", "user staged\n")
	git(repo, "add", "staged.txt")

	pub := gp.New(gp.Policy{Mode: gp.ModeCommit})
	// Attempt 1: force the post-commit `git reset` reconcile to fail by making
	// the real index read-only.
	if err := os.Chmod(repo+"/.git/index", 0o444); err != nil {
		panic(err)
	}
	res1, err1 := pub.Publish(context.Background(), gp.Request{
		Root: repo, Paths: []string{repo + "/owned.txt"}, Message: "stage one", Identity: "id-1",
	})
	fmt.Printf("attempt1: res=%+v err=%v\n", res1, err1)
	os.Chmod(repo+"/.git/index", 0o644)

	fmt.Printf("post-failure staged entries: %q\n", git(repo, "diff", "--cached", "--name-only"))
	fmt.Printf("post-failure HEAD touched: %q\n", git(repo, "show", "--pretty=format:", "--name-only", "HEAD"))

	// Attempt 2: plain retry with identical inputs.
	res2, err2 := pub.Publish(context.Background(), gp.Request{
		Root: repo, Paths: []string{repo + "/owned.txt"}, Message: "stage one", Identity: "id-1",
	})
	fmt.Printf("attempt2: res=%+v err=%v\n", res2, err2)
	fmt.Printf("after-retry staged entries (want empty or staged.txt only): %q\n", git(repo, "diff", "--cached", "--name-only"))
	fmt.Printf("owned blob in HEAD vs worktree equal: %v\n",
		git(repo, "rev-parse", "HEAD:owned.txt") == git(repo, "hash-object", repo+"/owned.txt"))
}
EOF
